# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Triton implementation of ``aten::_foreach_log2_`` (in-place, multi-tensor).

Semantics: for every tensor ``t`` in the list, ``t[i] = log2(t[i])`` written back
into ``t``'s own storage; the call returns ``None``.  Every element is read once
and written once, so the kernel is purely streaming.

Dispatch
--------
* one contiguous tensor  -> ``_log2_flat1``, a two-runtime-argument kernel (the
  launcher cost per runtime argument is measurable on this backend, so the
  single-tensor case keeps the smallest possible signature).
* several contiguous tensors sharing ``(dtype, numel)`` -> one fused launch:
  grid axis 0 selects the list slot, axis 1 partitions the element space, so the
  whole list costs a single launch instead of one per element.
* any other layout -> collapsed/stride-sorted kernel, one launch per tensor
  (correctness path; smallest-stride dim vectorised, outer dims resolved once
  per program).

Every program walks its share of tiles in a strided loop, so the tile stays
resident in the unified buffer while the prologue is amortised over many tiles.
No framework fallback is used: no ``torch.log2``, no ``.contiguous()`` staging,
no copy-back.  Launch concurrency comes from the driver-reported vector-core
count (never hard-coded) and falls back to one program per tile.
"""

import torch
import triton
import triton.language as tl

_MAXN = 16
_MAX_OUTER = 7
_WAVES = 8
_CAP_CACHE = {}
_FAST_CACHE = {}
_DRIVER = None

_TILE_BY_ITEMSIZE = {2: 8192, 4: 4096, 8: 2048}
_STRIDED_TILE = 2048


# ---------------------------------------------------------------------------
# kernels
# ---------------------------------------------------------------------------


@triton.jit
def _log2_flat1(x_ptr, n_elements, TILE: tl.constexpr, EVEN: tl.constexpr):
    nc = tl.num_programs(0)
    pid = tl.program_id(0)
    n_chunks = tl.cdiv(n_elements, TILE)
    elt = x_ptr.dtype.element_ty
    lane = tl.arange(0, TILE)
    if EVEN:
        # Software double buffer: the next tile's MTE2 load is issued before the
        # current tile is transformed and stored, so two transfers can be in
        # flight per core.  A loop-level num_stages hint was measured to have no
        # effect on this backend, so the overlap is expressed in the source.
        step = nc * TILE
        last = (n_chunks - 1) * TILE
        base = pid * TILE
        cur = tl.load(x_ptr + base + lane)
        for _ in range(tl.cdiv(n_chunks - pid, nc) - 1):
            nbase = tl.minimum(base + step, last)
            nxt = tl.load(x_ptr + nbase + lane)
            tl.store(x_ptr + base + lane, tl.log2(cur.to(tl.float32)).to(elt))
            cur = nxt
            base = nbase
        tl.store(x_ptr + base + lane, tl.log2(cur.to(tl.float32)).to(elt))
    else:
        for ck in tl.range(pid, n_chunks, nc, num_stages=2):
            offs = ck * TILE + lane
            mask = offs < n_elements
            x = tl.load(x_ptr + offs, mask=mask, other=1.0)
            tl.store(x_ptr + offs, tl.log2(x.to(tl.float32)).to(elt), mask=mask)


@triton.jit
def _log2_tiles(x_ptr, n_elements, ck0, nc, TILE: tl.constexpr, EVEN: tl.constexpr):
    n_chunks = tl.cdiv(n_elements, TILE)
    elt = x_ptr.dtype.element_ty
    if EVEN:
        lane = tl.arange(0, TILE)
        step = nc * TILE
        last = (n_chunks - 1) * TILE
        base = ck0 * TILE
        cur = tl.load(x_ptr + base + lane)
        for _ in range(tl.cdiv(n_chunks - ck0, nc) - 1):
            nbase = tl.minimum(base + step, last)
            nxt = tl.load(x_ptr + nbase + lane)
            tl.store(x_ptr + base + lane, tl.log2(cur.to(tl.float32)).to(elt))
            cur = nxt
            base = nbase
        tl.store(x_ptr + base + lane, tl.log2(cur.to(tl.float32)).to(elt))
    else:
        for ck in tl.range(ck0, n_chunks, nc, num_stages=2):
            offs = ck * TILE + tl.arange(0, TILE)
            mask = offs < n_elements
            x = tl.load(x_ptr + offs, mask=mask, other=1.0)
            tl.store(x_ptr + offs, tl.log2(x.to(tl.float32)).to(elt), mask=mask)


@triton.jit
def _log2_flat_fused(
    t0,
    t1,
    t2,
    t3,
    t4,
    t5,
    t6,
    t7,
    t8,
    t9,
    t10,
    t11,
    t12,
    t13,
    t14,
    t15,
    n_elements,
    NT: tl.constexpr,
    TILE: tl.constexpr,
    EVEN: tl.constexpr,
):
    ti = tl.program_id(0)
    ck0 = tl.program_id(1)
    nc = tl.num_programs(1)

    if ti == 0:
        _log2_tiles(t0, n_elements, ck0, nc, TILE, EVEN)
    if NT > 1:
        if ti == 1:
            _log2_tiles(t1, n_elements, ck0, nc, TILE, EVEN)
    if NT > 2:
        if ti == 2:
            _log2_tiles(t2, n_elements, ck0, nc, TILE, EVEN)
    if NT > 3:
        if ti == 3:
            _log2_tiles(t3, n_elements, ck0, nc, TILE, EVEN)
    if NT > 4:
        if ti == 4:
            _log2_tiles(t4, n_elements, ck0, nc, TILE, EVEN)
    if NT > 5:
        if ti == 5:
            _log2_tiles(t5, n_elements, ck0, nc, TILE, EVEN)
    if NT > 6:
        if ti == 6:
            _log2_tiles(t6, n_elements, ck0, nc, TILE, EVEN)
    if NT > 7:
        if ti == 7:
            _log2_tiles(t7, n_elements, ck0, nc, TILE, EVEN)
    if NT > 8:
        if ti == 8:
            _log2_tiles(t8, n_elements, ck0, nc, TILE, EVEN)
    if NT > 9:
        if ti == 9:
            _log2_tiles(t9, n_elements, ck0, nc, TILE, EVEN)
    if NT > 10:
        if ti == 10:
            _log2_tiles(t10, n_elements, ck0, nc, TILE, EVEN)
    if NT > 11:
        if ti == 11:
            _log2_tiles(t11, n_elements, ck0, nc, TILE, EVEN)
    if NT > 12:
        if ti == 12:
            _log2_tiles(t12, n_elements, ck0, nc, TILE, EVEN)
    if NT > 13:
        if ti == 13:
            _log2_tiles(t13, n_elements, ck0, nc, TILE, EVEN)
    if NT > 14:
        if ti == 14:
            _log2_tiles(t14, n_elements, ck0, nc, TILE, EVEN)
    if NT > 15:
        if ti == 15:
            _log2_tiles(t15, n_elements, ck0, nc, TILE, EVEN)


@triton.jit
def _log2_strided_kernel(
    x_ptr,
    n_inner,
    s_inner,
    n_chunks,
    n1,
    s1,
    n2,
    s2,
    n3,
    s3,
    n4,
    s4,
    n5,
    s5,
    n6,
    s6,
    n7,
    s7,
    BLOCK: tl.constexpr,
    NDIM: tl.constexpr,
):
    pid = tl.program_id(0)
    chunk = pid % n_chunks
    o = pid // n_chunks

    off = 0
    if NDIM > 0:
        i = o % n1
        o = o // n1
        off += i * s1
    if NDIM > 1:
        i = o % n2
        o = o // n2
        off += i * s2
    if NDIM > 2:
        i = o % n3
        o = o // n3
        off += i * s3
    if NDIM > 3:
        i = o % n4
        o = o // n4
        off += i * s4
    if NDIM > 4:
        i = o % n5
        o = o // n5
        off += i * s5
    if NDIM > 5:
        i = o % n6
        o = o // n6
        off += i * s6
    if NDIM > 6:
        i = o % n7
        o = o // n7
        off += i * s7

    idx = chunk * BLOCK + tl.arange(0, BLOCK)
    mask = idx < n_inner
    offs = off + idx * s_inner
    x = tl.load(x_ptr + offs, mask=mask, other=1.0)
    tl.store(
        x_ptr + offs,
        tl.log2(x.to(tl.float32)).to(x_ptr.dtype.element_ty),
        mask=mask,
    )


# ---------------------------------------------------------------------------
# host helpers
# ---------------------------------------------------------------------------


def _tile_for(dtype):
    return _TILE_BY_ITEMSIZE.get(dtype.itemsize, 2048)


def _program_cap(index):
    """Vector-core count x waves, queried from the driver (never hard-coded).

    ``0`` means "cap unavailable": the caller then launches one program per tile,
    which is always legal.
    """
    if index is None:
        index = 0
    cap = _CAP_CACHE.get(index, -1)
    if cap >= 0:
        return cap
    cap = 0
    try:
        from triton.runtime import driver as _driver

        props = _driver.active.utils.get_device_properties(index)
        cores = int(props.get("num_vectorcore") or props.get("num_aicore") or 0)
        if cores > 0:
            cap = cores * _WAVES
    except Exception:
        cap = 0
    _CAP_CACHE[index] = cap
    return cap


def _collapse(t):
    """Drop size-1 dims, sort ascending by stride, merge adjacent dims.

    Returns ``[(size, stride), ...]`` innermost first, or ``None`` if the tensor
    has no dimension larger than one (numel <= 1).
    """
    dims = [(sz, st) for sz, st in zip(t.shape, t.stride()) if sz != 1]
    if not dims:
        return None
    dims = sorted(dims, key=lambda p: p[1])
    merged = [dims[0]]
    for sz, st in dims[1:]:
        psz, pst = merged[-1]
        if st == pst * psz:
            merged[-1] = (psz * sz, pst)
        else:
            merged.append((sz, st))
    return merged


def _launch_strided(t):
    merged = _collapse(t)
    if merged is None:
        return
    n_inner, s_inner = merged[0]
    outer = merged[1 : _MAX_OUTER + 1]
    # Gather addressing needs an offset vector per lane on top of the data,
    # promote and result buffers, so the strided tile is kept smaller than the
    # flat one to stay inside the unified buffer.
    block = _STRIDED_TILE
    n_chunks = triton.cdiv(n_inner, block)
    total = n_chunks
    args = []
    for i in range(_MAX_OUTER):
        if i < len(outer):
            sz, st = outer[i]
            args.append(sz)
            args.append(st)
            total *= sz
        else:
            args.append(1)
            args.append(0)
    _log2_strided_kernel[(total,)](
        t, n_inner, s_inner, n_chunks, *args, block, len(outer)
    )


def _stream_for(index):
    global _DRIVER
    if _DRIVER is None:
        from triton.runtime import driver as _driver_module

        _DRIVER = _driver_module
    return _DRIVER.active.get_current_stream(index)


def _launch_flat_group(dtype, n, group):
    tile = _tile_for(dtype)
    even = (n % tile) == 0
    chunks = triton.cdiv(n, tile)
    dev = group[0].get_device()
    cap = _program_cap(dev)
    count = len(group)
    if count == 1:
        t = group[0]
        nc = min(chunks, cap) if cap > 0 else chunks
        # Fast path: replay the compiled kernel through its own launcher entry,
        # skipping the generic JIT wrapper (compile-option pass, parameter
        # binding, cache-key construction and metadata lookup) that the profile
        # showed dominates the small/medium workloads.  The cache key covers
        # every value the specialization depends on, and any failure falls back
        # to the generic launch.
        key = (dtype, n, tile, even, t.data_ptr() & 15, dev)
        ent = _FAST_CACHE.get(key)
        if ent is not None:
            try:
                ent[0](
                    nc,
                    1,
                    1,
                    _stream_for(dev),
                    ent[1],
                    ent[2],
                    None,
                    None,
                    None,
                    t,
                    n,
                    tile,
                    even,
                )
                return
            except Exception:
                _FAST_CACHE.pop(key, None)
        ck = _log2_flat1[(nc,)](t, n, tile, even)
        try:
            _FAST_CACHE[key] = (ck.foreach_log2_, ck.function, ck.packed_metadata)
        except Exception:
            pass
        return
    for start in range(0, count, _MAXN):
        part = group[start : start + _MAXN]
        nt = len(part)
        if cap > 0:
            nc = min(chunks, max(1, cap // nt))
        else:
            nc = chunks
        args = part + [part[0]] * (_MAXN - nt) if nt < _MAXN else part
        key = (
            dtype,
            n,
            tile,
            even,
            nt,
            dev,
            tuple(t.data_ptr() & 15 for t in part),
        )
        ent = _FAST_CACHE.get(key)
        if ent is not None:
            try:
                ent[0](
                    nt,
                    nc,
                    1,
                    _stream_for(dev),
                    ent[1],
                    ent[2],
                    None,
                    None,
                    None,
                    *args,
                    n,
                    nt,
                    tile,
                    even,
                )
                continue
            except Exception:
                _FAST_CACHE.pop(key, None)
        ck = _log2_flat_fused[(nt, nc)](*args, n, nt, tile, even)
        try:
            _FAST_CACHE[key] = (ck.foreach_log2_, ck.function, ck.packed_metadata)
        except Exception:
            pass


# ---------------------------------------------------------------------------
# entry point
# ---------------------------------------------------------------------------


def foreach_log2_(self, *extra):
    if extra:
        if isinstance(self, torch.Tensor):
            tensors = (self,) + extra
        else:
            raise TypeError("argument 'self' must be tuple of Tensors")
    else:
        tensors = self

    if not isinstance(tensors, (list, tuple)):
        raise TypeError("argument 'self' must be tuple of Tensors")
    if len(tensors) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")

    # One pass: validate, classify and group.  The in-place overlap rule only
    # needs a stride scan for non-contiguous tensors (a contiguous tensor is
    # dense and cannot alias), which avoids a dispatcher call per element of the
    # list - the dominant host cost for long lists.
    groups = {}
    other = []
    for t in tensors:
        if not isinstance(t, torch.Tensor):
            raise TypeError("argument 'self' must be tuple of Tensors")
        if not t.dtype.is_floating_point:
            raise RuntimeError(
                "result type Float can't be cast to the desired output type "
                f"{str(t.dtype).replace('torch.', '').capitalize()}"
            )
        if t.is_contiguous():
            n = t.numel()
            if n == 0:
                continue
            key = (t.dtype, n)
            group = groups.get(key)
            if group is None:
                groups[key] = [t]
            else:
                group.append(t)
        else:
            for size, stride in zip(t.shape, t.stride()):
                if size > 1 and stride == 0:
                    raise RuntimeError(
                        "unsupported operation: more than one element of the "
                        "written-to tensor refers to a single memory location. "
                        "Please clone() the tensor before performing the "
                        "operation."
                    )
            other.append(t)

    for t in other:
        if t.numel() != 0:
            _launch_strided(t)

    for (dtype, n), group in groups.items():
        _launch_flat_group(dtype, n, group)

    return None
